using System.Collections;

namespace Gori.StaticInstances.Testing.TestData;

public class SingletonGenerator_TestData : IEnumerable<TheoryDataRow<ISimpleTestData>>
{
    public const string TestPrefix = "Singleton";

    public const string Category = "Generator\\Singleton";

    public const string DefaultExpected =
        """
        // <auto-generated/>
        #nullable enable
        partial class MyService
        {
            private MyService () { }
            public static MyService Instance { get; } = new MyService();
        }
        """;

    public IEnumerator<TheoryDataRow<ISimpleTestData>> GetEnumerator()
    {

        // -------------------------------------------------------------------------
        // Single option behaviors - Name + Internal
        // -------------------------------------------------------------------------

        string prefix = $"{TestPrefix} All Options";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Name = "MyInstance", Type = InstanceType.WeakLockless, Constructor = Constructor.Off, Internal = true)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private static readonly WeakReference<MyService> _myInstance = new WeakReference<MyService>(null!);

                    internal static MyService MyInstance
                    {
                        get
                        {
                            if (_myInstance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            currentInstance = new MyService();
                            _myInstance.SetTarget(currentInstance);
                            return currentInstance;
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: All non-defaults",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Name = "MyInstance", Type = InstanceType.Weak, Internal = true)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private MyService () { }

                #if NET9_0_OR_GREATER
                    private static readonly Lock _weakLock = new Lock();
                #else
                    private static readonly object _weakLock = new object();
                #endif

                    private static readonly WeakReference<MyService> _myInstance = new WeakReference<MyService>(null!);

                    internal static MyService MyInstance
                    {
                        get
                        {
                            if (_myInstance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            lock(_weakLock)
                            {
                                if (_myInstance.TryGetTarget(out currentInstance))
                                {
                                    return currentInstance;
                                }

                                currentInstance = new MyService();
                                _myInstance.SetTarget(currentInstance);
                                return currentInstance;
                            }
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: All non-defaults except Constructor and ThreadSafe",
        };

        // -------------------------------------------------------------------------
        // Default behavior, no options
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Default Behavior";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService { }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService
                {
                    static MyService() { }
                }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Class with static constructor",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService () { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Existing primary default constructor",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService
                {
                    private MyService () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Existing private default constructor",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService
                {
                    public MyService (int value) { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category, "Would Fail to Compile but Expected"] } },
            Label = $"{prefix}: Existing public constructor with parameters",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton]
                public partial class MyService<T> { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService<T>
                {
                    private MyService () { }
                    public static MyService<T> Instance { get; } = new MyService<T>();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Generic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                namespace My.App
                {
                    [Singleton]
                    public partial class MyService { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                namespace My.App
                {
                    partial class MyService
                    {
                        private MyService () { }
                        public static MyService Instance { get; } = new MyService();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class in namespace",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer
                {
                    [Singleton]
                    public partial class Inner { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer
                {
                    partial class Inner
                    {
                        private Inner () { }
                        public static Inner Instance { get; } = new Inner();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class nested inside basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class GrandParent
                {
                    public partial class Parent
                    {
                        [Singleton]
                        public partial class Child { }
                    }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class GrandParent
                {
                    partial class Parent
                    {
                        partial class Child
                        {
                            private Child () { }
                            public static Child Instance { get; } = new Child();
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class deeply nested inside basic classes",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer<T>
                {
                    [Singleton]
                    public partial class Inner { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer<T>
                {
                    partial class Inner
                    {
                        private Inner () { }
                        public static Inner Instance { get; } = new Inner();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class nested inside generic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer
                {
                    [Singleton]
                    public partial class Inner<T> { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer
                {
                    partial class Inner<T>
                    {
                        private Inner () { }
                        public static Inner<T> Instance { get; } = new Inner<T>();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Generic class nested inside basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                public partial class Outer<TKey>
                {
                    [Singleton]
                    public partial class Inner<TValue> { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class Outer<TKey>
                {
                    partial class Inner<TValue>
                    {
                        private Inner () { }
                        public static Inner<TValue> Instance { get; } = new Inner<TValue>();
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Generic class nested inside generic class",
        };

        // -------------------------------------------------------------------------
        // Single option behaviors - Constructor
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Constructor";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Constructor = Constructor.Auto)]
                public partial class MyService { }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Default (Auto): Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Constructor = Constructor.Off)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Off: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Constructor = Constructor.On)]
                public partial class MyService () { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = On: Basic class with primary default constructor.",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Constructor = Constructor.On)]
                public partial class MyService 
                {
                    public MyService () { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = On: Basic class with default constructor.",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Constructor = Constructor.On)]
                public partial class MyService 
                {
                    public MyService (int value) { }
                }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private MyService () { }
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = On: Basic class with no default constructor, but has other constructors.",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Constructor = Constructor.On)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private MyService () { }
                    public static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = On: Basic class with no constructors.",
        };

        // -------------------------------------------------------------------------
        // Single option behaviors - Name
        // -------------------------------------------------------------------------

        prefix = $"{prefix} Name";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Name = "MyInstance")]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private MyService () { }
                    public static MyService MyInstance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix}: Basic class",
        };

        // -------------------------------------------------------------------------
        // Single option behaviors - Internal
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Internal";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Internal = false)]
                public partial class MyService { }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Default (false): Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Internal = true)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private MyService () { }
                    internal static MyService Instance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = true: Basic class",
        };

        // -------------------------------------------------------------------------
        // Multiple options - Name + Internal
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Name + Internal";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Name = "MyInstance", Internal = true)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable
                partial class MyService
                {
                    private MyService () { }
                    internal static MyService MyInstance { get; } = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = true: Basic class",
        };

        // -------------------------------------------------------------------------
        // Single option behaviors - Type
        // -------------------------------------------------------------------------

        prefix = $"{TestPrefix} Type";

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Property)]
                public partial class MyService { }
                """,
            Expected = DefaultExpected,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Default (Property): Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Field)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    private MyService () { }

                    public static readonly MyService Instance = new MyService();
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Field: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Lazy)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    private MyService () { }

                    private static readonly Lazy<MyService> _instance = new Lazy<MyService>(() => new MyService());

                    public static MyService Instance => _instance.Value;
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Lazy: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.Weak)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    private MyService () { }

                #if NET9_0_OR_GREATER
                    private static readonly Lock _weakLock = new Lock();
                #else
                    private static readonly object _weakLock = new object();
                #endif

                    private static readonly WeakReference<MyService> _instance = new WeakReference<MyService>(null!);

                    public static MyService Instance
                    {
                        get
                        {
                            if (_instance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            lock(_weakLock)
                            {
                                if (_instance.TryGetTarget(out currentInstance))
                                {
                                    return currentInstance;
                                }

                                currentInstance = new MyService();
                                _instance.SetTarget(currentInstance);
                                return currentInstance;
                            }
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = Weak: Basic class",
        };

        yield return new(new CSharpSyntaxTestData()
        {
            Input = """
                using Gori.StaticInstances;
                [Singleton(Type = InstanceType.WeakLockless)]
                public partial class MyService { }
                """,
            Expected = """
                // <auto-generated/>
                #nullable enable

                partial class MyService
                {
                    private MyService () { }
                    private static readonly WeakReference<MyService> _instance = new WeakReference<MyService>(null!);

                    public static MyService Instance
                    {
                        get
                        {
                            if (_instance.TryGetTarget(out MyService? currentInstance))
                            {
                                return currentInstance;
                            }

                            currentInstance = new MyService();
                            _instance.SetTarget(currentInstance);
                            return currentInstance;
                        }
                    }
                }
                """,
        })
        {
            Traits = { { "Category", [Category] } },
            Label = $"{prefix} = WeakLockless: Basic class",
        };
    }

    IEnumerator IEnumerable.GetEnumerator() => GetEnumerator();
}
